main.source:
fn main() {
    // create arrays
    let x = [13, 37, 72];
    let mut y = [5; 42];

    // get length
    assert!(x.len() == 3);
    assert!(y.len() == 42);

    // index read
    assert!(x[1] == 37);
    assert!(x[2] == 72);
    assert!(y[10] == 5);

    // index modify
    y[10] = 72;
    assert!(y[10] == 72);
    assert!(y[11] == 5);
}

array_len.source:
fn array_len() {
    let a = [0; 5];
    // this will internally do <a as &[i32]>::len(), i.e. auto-deref-coerce because `len` is a
    // method on slices, not arrays
    assert!(a.len() == 5);
}

